insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,sources,portraits,portrait_focus,works_total,style,pal,is_real,hidden,sort) values ('jmh','정명희','Jeong Myeong-hee','원로작가','한국화','{}'::text[],array['기산(箕山)','수묵담채','금강 연작','족보 시리즈','기행 사생']::text[],1945,'충남 홍성','대전',null,'금강을 40여 년 그려 온 한국화가','기산(箕山) 정명희는 1945년 충남 홍성에서 태어나 대전을 중심으로 활동해 온 한국화가다. 홍익대와 중앙대 예술대학원에서 공부했고, 1975년 대전 홍명미술관 첫 개인전 이후 개인전을 70여 회 열었다. 1970년대 족보 시리즈로 출발해 「금강 사계송」, 「대하 금강」, 「금강사랑」으로 이어지는 금강 연작을 40년 넘게 그렸고, 1990년대에는 백두산과 중국, 히말라야를 다니며 기행 작업을 남겼다. 대청댐 건설로 고향을 잃은 수몰민의 기억을 물과 함께 그린 작업도 있다. 2011년 작품 1,396점을 대전시교육청에 기증했고, 이 기증으로 2012년 대전평생학습관 안에 정명희미술관이 문을 열었다. 1977년 작 「새를 위해 금강은 반짝이고」는 2002년 중학교 미술 교과서에 실렸다. 시집 아홉 권과 시화집, 수필집, 자전소설 『슈파눙 쇼크』(2016)를 낸 문인이기도 하다.','[["2016","자전소설 『슈파눙 쇼크』 출간"],["2012","정명희미술관 개관 (대전평생학습관) · 올해의 작가상"],["2011","작품 1,396점을 대전시교육청에 기증"],["2002","「새를 위해 금강은 반짝이고」(1977) 중학교 미술 교과서 수록"],["","제4회 겸재미술상"],["1996","미술의 해 대전광역시 조직위원장"],["1993","대전광역시 문화상"],["1990","대한민국미술대전 심사위원"],["1989","안견미술상"],["1971–82","백양회·중앙미술대전·충남도전 특선 및 대상"]]'::jsonb,'[["2012","「금강의 희로애락」 · 정명희미술관 개관전","대전평생학습관 정명희미술관"],["2011","기증작품전","대전평생학습관 (임시 정명희미술관)"],["2005","황하에 흐르다","중앙미술관"],["2000","환경, 생명의 조형언어","공평화랑·갤러리 사비나(서울), 대전 문화원·현대화랑·창신화랑·오원화랑"],["1998","금강사랑 전국 6대 도시 순회전","서울 갤러리사바나, 대구 신미화랑, 부산 롯데화랑, 전주 갤러리휴먼, 광주 궁동갤러리, 대전 현대화랑"],["1997","다시 금강으로 전","대전 한림미술관, 공주문예회관"],["1996","중국기행전","대전 현대화랑"],["1995","금강에서 장강까지 사생리포트","서울 대림화랑"],["1993","금강사계연작 春夏秋冬전","대전 오원화랑"],["1992","신 금강전","서울 서초갤러리·청작미술관, 대전 오원화랑"],["1991","아! 백두산전","대전 오원화랑, 대구 중앙화랑"],["1989","대하 금강전 / 안견 미술상 수상기념전","서울 갤러리, 대전 문화원"],["1987","아름다운 금강전 / 기산 현대 수묵리전","서울 파르코문화센터, 대전 예가화랑"],["1986","아이러브 금강전","대전 신신화랑"],["1985","금강 사계송전 / 1000리 금강 송전","서울 갤러리, 대전 시민회관·공간사랑"],["1983","기산 정명희전","서울 동덕미술관, 대전 문화원화랑, 청주 청탑화랑"],["1982","정명희전","대전 공간사랑"],["1981","箕山 정명희전","서울 관훈미술관, 대전 시민회관"],["1977","一淸 정명희전","대전 홍명미술관"],["1975","一淸 정명희 작품전","대전 홍명미술관"]]'::jsonb,'국립현대미술관, 대영박물관, 서울시립미술관, 대전시립미술관, 한양대박물관, 대전대박물관, 충청남도 등 · 정명희미술관(기증작 1,396점)',array['『슈파눙 쇼크』 (자전소설, 2016)','「하늘을 나르는 물고기」 (화문집)','「백두산에서 히말라야까지」 (화문집)','「하늘그림자」 (시집, 1994)','「아침이 숲을 깨운다」 (시집)','「아메리카를 포기한다」 (시집)','「금강사랑-고백 혹은 변명」 (시집)']::text[],null,'[{"name":"한국예술디지털아카이브(DA-Arts) 미술작가 500人","url":"https://www.daarts.or.kr/visual/artist"},{"name":"한국교육신문 (2011, 작품 기증)","url":"https://hangyo.com/mobile/article.html?no=63917"},{"name":"대전일보 (정명희미술관)","url":"http://www.daejonilbo.com/news/articleView.html?idxno=1264196"},{"name":"대전투데이 (2016, 초대전·자전소설)","url":"http://www.daejeontoday.com/news/articleView.html?idxno=411028"},{"name":"금강일보 (2016, 『슈파눙 쇼크』)","url":"http://www.ggilbo.com/news/articleView.html?idxno=283360"},{"name":"충청뉴스 (2022, 소장전)","url":"https://www.ccnnews.co.kr/news/articleView.html?idxno=247133"},{"name":"뉴스서울 (2023, 소장전)","url":"https://newsseoul.co.kr/news/view/1065575414203779"}]'::jsonb,array['artists/jmh/photos/01.jpg','artists/jmh/photos/02.jpg']::text[],array[0.5,0.12]::real[],null,'ink',array['#ECE8DF','#1C1C1C','#6B6A64','#8A3B2E','#C9C2B3']::text[],true,false,10);
