insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,sources,portraits,portrait_focus,works_total,style,pal,is_real,hidden,sort) values ('lmg','이민구',null,'중견작가','설치·복합매체',array['서양화']::text[],array['거미줄 작가','소우주(Microcosmos)','혼합재료','자동차 도료·단청 안료']::text[],null,null,null,'희소성과 개성이 강한 독보적인 작가로 남고 싶다','자연에서 거둔 거미줄로 짓는 「소우주」','이민구는 ''거미줄 작가''로 불린다. 1997년 논산의 창작실에 입주해 작업하다 거미줄을 만난 뒤, 자연에서 직접 채집한 거미줄을 화면에 옮기는 「소우주(Microcosmos)」 연작을 이어 왔다. 거미줄 위에 자동차 도색용 물감과 단청 물감을 쓰고, 붓 대신 손으로 물감을 펴 바르거나 물감을 짜내 선을 세우고 칼로 그어 빛과 속도감을 만든다. 검은 바탕의 은빛 거미줄과 흰 바탕의 검은 거미줄을 엇갈려 놓은 격자 작업도 있다. 원색보다 시간이 지나며 바랜 깊은 색을 즐겨 쓰는데, 어린 시절 자주 찾던 산사와 초가·기와집에서 산 기억이 바탕이 되었다고 한다. 작가에게 거미줄은 얽히고설킨 사람 사이의 관계이자 오늘의 네트워크, 나아가 우주를 떠올리게 하는 그물이다. 한국미술협회와 대전현대미술협회 회원이며 목원대학교 강사를 지냈다.','[["","소사벌미술대전 운영위원"],["","보문미술대전·대한민국여성미술대전 심사위원"],["","목원대학교 강사 역임"],["","한국미술협회·대전현대미술협회 회원"]]'::jsonb,'[["2017","초대 개인전","경주 라우갤러리"]]'::jsonb,'국립현대미술관 미술은행, 대전시립미술관, 목원대학교','{}'::text[],null,'[{"name":"경북매일 (2017, 라우갤러리 초대전)","url":"https://kbmaeil.com/article/201704040188929"},{"name":"경북일보 (2017.3.31)","url":"https://www.kyongbuk.co.kr/news/articleView.html?idxno=989233"}]'::jsonb,'{}'::text[],null,null,'lines',array['#EFE7D6','#2B2620','#8A7B60','#B9A27A','#141210']::text[],true,false,20);
