insert into public.works (artist_id,sort,title,year,material,size,description,image_path) values ('lmg',12,'소우주 (Microcosmos)',null,'혼합재료 (거미줄)',null,'밝은 화면과 어두운 화면을 짝지은 작업. 「소우주(Microcosmos)」 연작 · 제목 확인 중','artists/lmg/works/13.jpg');
insert into public.works (artist_id,sort,title,year,material,size,description,image_path) values ('lmg',13,'소우주 (Microcosmos)',null,'혼합재료 (거미줄)',null,'밝은 화면과 어두운 화면을 짝지은 작업. 「소우주(Microcosmos)」 연작 · 제목 확인 중','artists/lmg/works/14.jpg');
insert into public.artists (id,name,en,tier,genre,more,tags,born,birthplace,city,quote,line,bio,cv,history,collections,pubs,source,sources,portraits,portrait_focus,works_total,style,pal,is_real,hidden,sort) values ('lhw','이홍원','Lee Hongwon','원로작가','서양화','{}'::text[],array['李鴻遠','마동창작마을','해학과 풍자','한지 부조','호랑이']::text[],1955,null,'청주',null,'익살과 해학으로 그리는 사람과 자연의 노래','이홍원(李鴻遠)은 1955년생 서양화가로, 동국대학교와 같은 대학원에서 서양화를 전공했다. 1984년 첫 개인전 「삶의 노래」를 연 뒤 개인전·초대전·기획전·해외전을 합쳐 300회 넘게 전시했고, 중국 상하이, 미국 LA와 뉴욕, 일본, 사라예보, 페루에서도 작품을 선보였다. 1995년 청주 문의면 마동리의 폐교(옛 회인초 회서분교장)로 작업실을 옮겼고, 이곳은 작가들이 모여 작업하는 ''마동창작마을''이 되었다. 1985년부터 캔버스 위에 한지로 부조를 만들고 유화·아크릴·동양화 물감을 함께 써서 채색해 왔다. 호랑이와 소, 닭, 말 같은 동물, 악기를 연주하는 사람들, 꽃나무를 따뜻한 색과 익살스러운 선으로 그리며, 풍자와 해학 속에 사람의 삶과 자연의 순환, 화합과 상생을 담는다. 예술은 특별한 것이 아니라 일상이고 삶 속에 있다는 것이 작가의 생각이다. 충북민미협과 충북민예총 회장을 지냈다.','[["2026","태극코리아와 협업한 생활문화상품 출시"],["2013","올해의좋은작가상 (무심갤러리)"],["2006","국립현대미술관 작품 소장"],["2004","단재 신채호 영정 제작"],["1995","청주 문의면 마동리에 작업실 마련 (마동창작마을)"],["","충북민족미술인협회·충북민족예술인총연합 회장 역임"],["","해외전: 중국 상하이, 미국 LA·뉴욕, 일본, 사라예보, 페루"]]'::jsonb,'[["2008","마동창작마을 오픈스튜디오전","청주 마동창작마을"],["1984","첫 개인전 「삶의 노래」","서울 (장소 확인 중)"]]'::jsonb,'국립현대미술관 (2006)','{}'::text[],null,'[{"name":"사람과사회 인터뷰 「예술은 일상이고, 삶에 존재한다」 (2018)","url":"https://peopleciety.com/archives/13431"},{"name":"동아일보 (2025.3.13, 마동 30년 기념특별전)","url":"https://news.nate.com/view/20250313n28204?mid=n1101"},{"name":"문화체육관광부 문화 행사 안내","url":"https://mcst.go.kr/site/s_culture/culture/cultureView.jsp?pSeq=48181"},{"name":"디지털청주문화대전 (마동창작마을)","url":"https://cheongju.grandculture.net/cheongju/toc/GC00203704?search=TT054"},{"name":"중부매일 (2023.6.21)","url":"https://www.jbnews.com/news/articleView.html?idxno=1398041"},{"name":"전국매일","url":"https://www.jeonmae.co.kr/news/articleView.html?idxno=1280267"},{"name":"충청타임즈 (2008, 오픈스튜디오전)","url":"https://www.cctimes.kr/news/articleView.html?idxno=106468"}]'::jsonb,'{}'::text[],null,null,'bands',array['#F4EEE4','#1F3B73','#E2A13B','#C8443A','#2D2A26']::text[],true,false,30);
