insert into public.exhibitions (id,gallery_id,title,kind,start_date,end_date,artists,description) values ('ex01','cbcc','이홍원 작은 그림전 – 마동 30년 기념특별전','특별전','2025-03-11','2025-03-16',array['lhw']::text[],'청주 마동창작마을에서 작업한 30년을 기념해 충북문화관 숲속갤러리 전관에서 연 작은 그림전. 꽃 호랑이, 소나무, 싸움소, 질주, 연리지, 울림 등을 선보였다.');
insert into public.exhibitions (id,gallery_id,title,kind,start_date,end_date,artists,description) values ('ex02','insaplaza','이홍원 전 – 달항아리 노래','기획 초대전','2023-03-22','2023-03-27',array['lhw']::text[],'서울 인사아트프라자갤러리 기획 초대전.');
insert into public.exhibitions (id,gallery_id,title,kind,start_date,end_date,artists,description) values ('ex03','jmhm','물, 예술을 넘어','소장전','2023-02-06','2023-06-30',array['jmh']::text[],'대청댐 건설로 고향을 잃은 수몰민의 애환을 담은 작품들. 제4회 겸재미술상 수상기념전에 걸렸던 작품을 다시 소개했다.');
insert into public.exhibitions (id,gallery_id,title,kind,start_date,end_date,artists,description) values ('ex04','jmhm','한 장의 편지 – 한 숟가락의 물','소장전','2022-02-07','2022-06-30',array['jmh']::text[],'''금강 아리랑, 이 한잔의 물''을 부제로, 물과 고향을 주제로 한 작품을 모은 소장전.');
insert into public.exhibitions (id,gallery_id,title,kind,start_date,end_date,artists,description) values ('ex05','dmma','금강홍 열두가지 변주','초대전','2016-06-14','2016-06-19',array['jmh']::text[],'대전시립미술관 초대전.');
insert into public.notices (tag,title,body,date) values ('안내','arttan 주소는 www.arttan.co.kr 이에요','art(미술)와 灘(여울 탄)을 합친 이름이에요.','2026.09.28');
insert into public.notices (tag,title,body,date) values ('안내','작가 등록 신청은 이렇게 해요','위쪽의 ''작가 등록'' 버튼으로 신청하면 운영팀이 확인한 뒤 승인해요. 작가 공간 개설과 작품 아카이브는 모두 무료예요.','2026.09.29');
insert into public.notices (tag,title,body,date) values ('공지','세 작가의 공간으로 새로 시작해요','작품 이미지 사용을 허락받은 기산 정명희, 이민구, 이홍원 작가의 공간을 먼저 열었어요. 시안에 넣었던 예시 작가와 예시 전시는 모두 지웠어요. 작가 소개는 공개된 기사와 자료를 바탕으로 arttan이 정리했고, 출처를 작가 공간에 함께 적어 두었어요.','2026.10.06');
